<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import Search from "lucide-vue-next/dist/esm/icons/search.js"
import ArrowRight from "lucide-vue-next/dist/esm/icons/arrow-right.js"
import ArrowUpRight from "lucide-vue-next/dist/esm/icons/arrow-up-right.js"
import Heart from "lucide-vue-next/dist/esm/icons/heart.js"
import Trees from "lucide-vue-next/dist/esm/icons/trees.js"
import Castle from "lucide-vue-next/dist/esm/icons/castle.js"
import Bike from "lucide-vue-next/dist/esm/icons/bike.js"
import Footprints from "lucide-vue-next/dist/esm/icons/footprints.js"
import Utensils from "lucide-vue-next/dist/esm/icons/utensils.js"
import Bed from "lucide-vue-next/dist/esm/icons/bed.js"
import MapPin from "lucide-vue-next/dist/esm/icons/map-pin.js"
import Clock3 from "lucide-vue-next/dist/esm/icons/clock-3.js"
import Signal from "lucide-vue-next/dist/esm/icons/signal.js"
import X from "lucide-vue-next/dist/esm/icons/x.js"
import Plus from "lucide-vue-next/dist/esm/icons/plus.js"
import Minus from "lucide-vue-next/dist/esm/icons/minus.js"
import Download from "lucide-vue-next/dist/esm/icons/download.js"
import ChevronRight from "lucide-vue-next/dist/esm/icons/chevron-right.js"
import ChevronUp from "lucide-vue-next/dist/esm/icons/chevron-up.js"
import ChevronDown from "lucide-vue-next/dist/esm/icons/chevron-down.js"
import Compass from "lucide-vue-next/dist/esm/icons/compass.js"
import SlidersHorizontal from "lucide-vue-next/dist/esm/icons/sliders-horizontal.js"
import Route from "lucide-vue-next/dist/esm/icons/route.js"
import Check from "lucide-vue-next/dist/esm/icons/check.js"
import Menu from "lucide-vue-next/dist/esm/icons/menu.js"
import LogOut from "lucide-vue-next/dist/esm/icons/log-out.js"
import Leaf from "lucide-vue-next/dist/esm/icons/leaf.js"
import Mountain from "lucide-vue-next/dist/esm/icons/mountain.js"
import Navigation from "lucide-vue-next/dist/esm/icons/navigation.js"
import Mail from "lucide-vue-next/dist/esm/icons/mail.js"
import { places as initialPlaces, categories, trails } from './data'
import TravelMap from './components/TravelMap.vue'
import PlaceCommunity from './components/PlaceCommunity.vue'
import ExploreHome from './components/ExploreHome.vue'
import { useRouting, buildGpx } from './useRouting.js'
const icons = { trees: Trees, castle: Castle, bike: Bike, footprints: Footprints, utensils: Utensils, bed: Bed }
function read(key, fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback } catch { return fallback } }
const places=ref(initialPlaces), view=ref('explore'), category=ref('all'), query=ref(''), selected=ref(read('perly-route',[1,5,3])), favorites=ref(read('perly-favorites',[])), saved=ref(read('perly-saved',[])), modal=ref(null), detail=ref(null), toast=ref(''), menu=ref(false), onlyFavorites=ref(false), transport=ref('bike'), apiOnline=ref(false), user=ref(read('perly-user',null)), token=ref(localStorage.getItem('perly-token') || ''), authMode=ref('login'), authEmail=ref(''), authPassword=ref(''), authName=ref(''), authError=ref(''), busy=ref(false), routeName=ref('Moja lubuska przygoda')
let toastTimer
onBeforeUnmount(()=>clearTimeout(toastTimer))
const serverSaved=ref([]), trailFilter=ref('all')
const returnToPlace=ref(null)
const googleMapsUrl=computed(()=>detail.value?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${detail.value.lat},${detail.value.lng}`)}`:'')
function requestPlaceLogin(){returnToPlace.value=detail.value;modal.value='auth'}
watch(modal,(value,previous)=>{if(previous==='auth'&&value===null)returnToPlace.value=null})
const savedPlans=computed(()=>user.value&&apiOnline.value?serverSaved.value:saved.value)
const filtered=computed(()=>places.value.filter(p=>(category.value==='all'||p.category===category.value)&&(!onlyFavorites.value||favorites.value.includes(p.id))&&`${p.name} ${p.subtitle} ${p.location}`.toLocaleLowerCase('pl').includes(query.value.toLocaleLowerCase('pl'))))
const selectedPlaces=computed(()=>selected.value.map(id=>places.value.find(p=>p.id===id)).filter(Boolean))
const featured=computed(()=>category.value==='all'&&!query.value&&!onlyFavorites.value? filtered.value.slice(0,4):filtered.value)
const straightDistance=computed(()=>{let total=0; for(let i=1;i<selectedPlaces.value.length;i++){const a=selectedPlaces.value[i-1],b=selectedPlaces.value[i],r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlng=(b.lng-a.lng)*r; const h=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlng/2)**2;total+=6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}return Math.round(total)})
const {route:computedRoute,loading:routeLoading,error:routeError,refresh:refreshRoute}=useRouting({ids:selected,transport,enabled:computed(()=>view.value==='planner'),online:apiOnline})
const distance=computed(()=>computedRoute.value?new Intl.NumberFormat('pl',{maximumFractionDigits:1}).format(computedRoute.value.distance_m/1000):straightDistance.value)
const travelTime=computed(()=>{if(computedRoute.value){const minutes=Math.max(1,Math.round(computedRoute.value.duration_s/60));return minutes<60?minutes+' min':Math.floor(minutes/60)+' h '+minutes%60+' min'}return '—'})

watch(selected,v=>localStorage.setItem('perly-route',JSON.stringify(v)),{deep:true})
watch(favorites,v=>localStorage.setItem('perly-favorites',JSON.stringify(v)),{deep:true})
watch(saved,v=>localStorage.setItem('perly-saved',JSON.stringify(v)),{deep:true})
async function api(path,options={}) {const response=await fetch(`/api${path}`,{signal:AbortSignal.timeout(8000),...options, headers:{'Content-Type':'application/json',...(token.value?{Authorization:`Bearer ${token.value}`} :{}),...options.headers}}); if(!response.ok){let msg='Nie udało się wykonać operacji.'; try{const data=await response.json(); if(typeof data.detail==='string')msg=data.detail}catch{}throw new Error(msg)}return response.status===204?null:response.json()}
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4000)}
function navigate(target){view.value=target;menu.value=false;onlyFavorites.value=false;category.value='all';query.value='';window.scrollTo({top:0,behavior:'smooth'})}
function focusSearch(){navigate('explore');nextTick(()=>document.getElementById('explore-query')?.focus())}
function chooseCategory(id){if(id==='bike'||id==='walk'){transport.value=id;trailFilter.value=trailFilter.value===id?'all':id;document.querySelector('#trails')?.scrollIntoView({behavior:'smooth'});return}category.value=category.value===id?'all':id;document.querySelector('#places')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function toggleFavorite(id){const exists=favorites.value.includes(id);favorites.value=exists?favorites.value.filter(x=>x!==id):[...favorites.value,id];if(user.value&&apiOnline.value){try{await api(`/favorites/${id}`,{method:exists?'DELETE':'PUT'})}catch(e){favorites.value=exists?[...favorites.value,id]:favorites.value.filter(x=>x!==id);notify(e.message)}}}
function togglePlace(id){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function move(index,delta){const list=[...selected.value];[list[index],list[index+delta]]=[list[index+delta],list[index]];selected.value=list}
function openDetail(place){detail.value=place;modal.value='detail'}
function planTrail(trail){selected.value=[...trail.ids];transport.value=trail.type;navigate('planner');notify('Dodano miejsca z inspiracji. Uzupełnij swój plan.')} 
function showFavorites(){navigate('discover');onlyFavorites.value=true;setTimeout(()=>document.querySelector('#places')?.scrollIntoView({behavior:'smooth'}),50)}
function search(){if(view.value!=='discover')view.value='discover';setTimeout(()=>document.querySelector('#places')?.scrollIntoView({behavior:'smooth'}),50)}
async function saveRoute(){if(!selected.value.length)return notify('Najpierw dodaj miejsce do swojej trasy.');const route={name:routeName.value.trim(),place_ids:[...selected.value],transport:transport.value};if(user.value&&apiOnline.value){try{const result=await api('/routes',{method:'POST',body:JSON.stringify(route)});serverSaved.value=[result,...serverSaved.value]}catch(e){notify(e.message);return}}else{saved.value=[...saved.value,{...route,id:Date.now()}]}notify(user.value&&apiOnline.value?'Trasa została zapisana na koncie.':'Trasa zapisana na tym urządzeniu.');modal.value=null}
async function deleteSaved(route){if(user.value&&apiOnline.value){try{await api(`/routes/${route.id}`,{method:'DELETE'});serverSaved.value=serverSaved.value.filter(r=>r.id!==route.id)}catch(e){notify(e.message)}}else{saved.value=saved.value.filter(r=>r.id!==route.id)}}
function exportGpx(){if(!selected.value.length||routeLoading.value)return;const xml=buildGpx(routeName.value,selectedPlaces.value,computedRoute.value);const url=URL.createObjectURL(new Blob([xml],{type:'application/gpx+xml'}));const a=document.createElement('a');a.href=url;a.download='perly-ziemi-lubuskiej.gpx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(computedRoute.value?'Pobrano trasę GPX.':'Pobrano punkty GPX — bez przebiegu po drogach.')}

async function authenticate(){busy.value=true;authError.value='';try{const result=await api(`/auth/${authMode.value}`,{method:'POST',body:JSON.stringify({email:authEmail.value,password:authPassword.value,name:authName.value})});token.value=result.access_token;user.value=result.user;localStorage.setItem('perly-token',token.value);localStorage.setItem('perly-user',JSON.stringify(user.value));const [remote,routes]=await Promise.all([api('/favorites'),api('/routes')]);favorites.value=remote;serverSaved.value=routes;if(returnToPlace.value){detail.value=returnToPlace.value;returnToPlace.value=null;modal.value='detail'}else{modal.value=null}authPassword.value='';notify('Witaj! Czas na kolejną przygodę.')}catch(e){authError.value=e.message}finally{busy.value=false}}
function logout(){user.value=null;token.value='';localStorage.removeItem('perly-user');localStorage.removeItem('perly-token');notify('Wylogowano.')}
onMounted(async()=>{try{const result=await api('/places', {signal:AbortSignal.timeout(3500)});if(!Array.isArray(result))throw new Error('Invalid catalog');places.value=result;apiOnline.value=true}catch{apiOnline.value=false}if(apiOnline.value&&user.value){try{const [remote,routes]=await Promise.all([api('/favorites'),api('/routes')]);favorites.value=remote;serverSaved.value=routes}catch{logout();notify('Sesja wygasła. Zaloguj się ponownie.')}}})
let previousFocus
watch(modal,async value=>{if(value){previousFocus=document.activeElement;await nextTick();document.querySelector('.modal')?.focus()}else previousFocus?.focus?.()})
function trapFocus(event){if(event.key!=='Tab')return;const items=[...document.querySelectorAll('.modal button:not([disabled]),.modal input:not([disabled]),.modal textarea:not([disabled]),.modal select:not([disabled]),.modal a[href]')];const first=items[0],last=items.at(-1);if(!first)return;if(event.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
</script>

<template>
 <header class="site-header">
  <a href="#" class="brand" @click.prevent="navigate('explore')" aria-label="Perły Ziemi Lubuskiej — strona główna">
   <svg class="brand-mark" viewBox="0 0 76 70" aria-hidden="true"><circle cx="53" cy="21" r="13" fill="#f5b82f"/><path d="M22 5 5 27h10L2 43h40L30 27h9Z" fill="#19754f"/><path d="m39 20-11 15h6l-8 12h27l-9-12h6Z" fill="#268459"/><path d="M7 52q18-12 37-3t28-1l-8 9q-19-8-35 1T7 52" fill="#087eac"/><path d="M15 63q16-8 31-3t16 1q-21 13-47 2" fill="#0b95bd"/><path d="M21 38v12" stroke="#fff" stroke-width="3"/></svg>
   <span>Perły<br>Ziemi Lubuskiej</span>
  </a>
  <nav :class="{open:menu}" aria-label="Nawigacja główna">
   <button :class="{active:view==='explore'}" @click="navigate('explore')">Szukaj miejsc</button>
   <button :class="{active:view==='discover'&&!onlyFavorites}" @click="navigate('discover')">Odkrywaj</button>
   <button :class="{active:view==='planner'}" @click="navigate('planner')">Mapa i trasy</button>
   <button @click="navigate('discover');category='food';search()">Jedzenie</button>
   <button :class="{active:view==='about'}" @click="navigate('about')">O regionie</button>
  </nav>
  <div class="header-actions"><button class="icon-btn search-nav" aria-label="Szukaj miejsc" @click="focusSearch"><Search :size="22"/></button><button class="icon-btn favorites-nav" aria-label="Ulubione miejsca" @click="showFavorites"><Heart :size="23"/><span v-if="favorites.length" class="count-dot">{{favorites.length}}</span></button><button v-if="!user" class="button login-btn" @click="modal='auth'">Zaloguj się <ArrowUpRight :size="15"/></button><button v-else class="button login-btn" @click="logout">{{user.name || 'Wyloguj'}} <LogOut :size="16"/></button><button class="icon-btn mobile-menu" @click="menu=!menu" aria-label="Otwórz menu"><Menu/></button></div>
 </header>

 <ExploreHome v-if="view==='explore'" :places="places" :favorites="favorites" @open="openDetail" @favorite="toggleFavorite" @planner="navigate('planner')"/>
 <main v-else-if="view==='discover'">
  <section class="hero">
   <div class="hero-shade"></div><div class="hero-inner content-width"><div class="eyebrow"><span></span> MAŁE PODRÓŻE. WIELKIE ODKRYCIA.</div><h1>Odkrywaj<br><em>Ziemię Lubuską.</em></h1><p>Jeziora, lasy, zamki i niezwykłe historie.<br>Miejsca, do których chce się wracać.</p><form class="hero-search" @submit.prevent="search"><Search :size="23"/><input ref="searchInput" v-model="query" placeholder="Dokąd zabierze Cię ciekawość?" aria-label="Szukaj miejsc i atrakcji"><button aria-label="Wyszukaj"><ArrowRight :size="25"/></button></form><div class="hero-hint"><MapPin :size="14"/> Łagów — mała perła, wielki zachwyt</div></div>
   <div class="hero-note">Najlepsze historie<br>zaczynają się <i>blisko.</i><svg viewBox="0 0 180 20"><path d="M4 15Q90-3 175 6M26 19Q94 7 154 10" fill="none" stroke="currentColor" stroke-width="4"/></svg></div><div class="photo-credit">Wizualizacje na podstawie materiałów referencyjnych</div>
  </section>
  <div class="content-width">
   <section class="category-grid" aria-label="Kategorie atrakcji"><button v-for="cat in categories" :key="cat.id" :class="['category-card',cat.color,{selected:category===cat.id||trailFilter===cat.id}]" @click="chooseCategory(cat.id)"><component :is="icons[cat.icon]" :size="32" :stroke-width="1.7"/><span>{{cat.name}}<small>{{cat.caption}}</small></span><ArrowUpRight :size="16" class="category-arrow"/></button></section>
   <section id="places" class="places-section"><div class="section-heading"><div><div class="section-kicker">TWOJA NASTĘPNA PRZYGODA</div><h2>{{onlyFavorites?'Twoje ulubione miejsca':category==='all'&&!query?'Miejsca, które zachwycają': 'Odkryj coś dla siebie'}}<span class="heading-dot">.</span></h2></div><button class="text-link" @click="category='all';query='';onlyFavorites=false;view='planner'">Zobacz na mapie <ArrowRight :size="18"/></button></div>
    <div v-if="query||category!=='all'||onlyFavorites" class="filter-bar"><span>{{filtered.length}} {{filtered.length===1?'miejsce':'miejsc'}} <template v-if="query">dla „{{query}}”</template></span><button @click="query='';category='all';onlyFavorites=false">Wyczyść filtry <X :size="14"/></button></div>
    <div v-if="featured.length" class="place-grid"><article v-for="place in featured" :key="place.id" class="place-card"><button class="place-image" @click="openDetail(place)"><img :src="place.image" :alt="place.name" loading="lazy"><span class="place-tag">{{categories.find(c=>c.id===place.category)?.name}}</span></button><button :class="['heart-btn',{liked:favorites.includes(place.id)}]" :aria-label="`${favorites.includes(place.id)?'Usuń z ulubionych':'Dodaj do ulubionych'}: ${place.name}`" :aria-pressed="favorites.includes(place.id)" @click="toggleFavorite(place.id)"><Heart :size="20" :fill="favorites.includes(place.id)?'currentColor':'none'"/></button><div class="place-info"><span class="place-location"><MapPin :size="12"/> {{place.location}}</span><button @click="openDetail(place)" class="place-title">{{place.name}}</button><p>{{place.subtitle}}</p><button class="card-arrow" :aria-label="`Zobacz ${place.name}`" @click="openDetail(place)"><ArrowUpRight :size="21"/></button></div></article></div>
    <div v-else class="empty-state"><Compass :size="36"/><h3>{{onlyFavorites?'Twoje odkrycia czekają na zapisanie':'Tutaj jeszcze nic nie znaleźliśmy'}}</h3><p>{{category==='stay'?'Baza noclegów jest w przygotowaniu. Tymczasem odkryj miejsca w okolicy.':'Spróbuj innej nazwy lub wybierz serduszko przy miejscu, które Cię zachwyci.'}}</p><button class="button" @click="query='';category='all';onlyFavorites=false">Odkrywaj miejsca <ArrowRight :size="16"/></button></div>
   </section>
   <section id="trails" class="trails-section"><div class="section-heading"><div><div class="section-kicker">PO DRODZE PO WSPOMNIENIA</div><h2>Obierz dobry kierunek<span class="heading-dot">.</span></h2></div><button class="text-link" @click="navigate('planner')">Zaplanuj własną trasę <ArrowRight :size="18"/></button></div><div class="trail-grid"><button v-for="trail in trails.filter(t=>trailFilter==='all'||t.type===trailFilter)" :key="trail.id" class="trail-card" @click="planTrail(trail)"><div class="trail-image"><img :src="trail.image" :alt="trail.name" loading="lazy"><span class="trail-label"><component :is="trail.type==='bike'?Bike:Footprints" :size="15"/>{{trail.type==='bike'?'Na dwóch kółkach':'Krok po kroku'}}</span></div><div class="trail-info"><h3>{{trail.name}}</h3><div class="trail-meta"><span><MapPin :size="14"/> ok. {{trail.distance}} km</span><span><Clock3 :size="14"/> {{trail.time}}</span><span><Signal :size="15"/>{{trail.difficulty}}</span></div><ArrowUpRight :size="21" class="trail-arrow"/></div></button></div><p class="small-note">Inspiracje wycieczek — orientacyjne parametry. Planer pozwala wybrać punkty do odwiedzenia.</p></section>
   <section class="journey-banner"><div class="journey-illustration"><Route :size="56" :stroke-width="1.1"/><span class="orb one"></span><span class="orb two"></span></div><div><div class="section-kicker">TWÓJ DZIEŃ. TWOJE TEMPO.</div><h2>Najpiękniejsza trasa? Twoja własna.</h2><p>Wybierz miejsca, połącz je w plan i ruszaj po swoje wspomnienia.</p></div><button class="button" @click="navigate('planner')">Zaplanuj wycieczkę <ArrowRight :size="18"/></button></section>
  </div>
 </main>

 <main v-else-if="view==='planner'" class="planner-page">
  <section class="planner-heading content-width"><div><div class="section-kicker">PRZYGODA ZACZYNA SIĘ OD POMYSŁU</div><h1>Zaplanuj swoją trasę<span class="heading-dot">.</span></h1><p>Wybierz swoje perły. Resztę zostaw ciekawości.</p></div><button class="text-link" @click="modal='saved'">Zapisane plany <Heart :size="17"/></button></section>
  <section class="planner-layout"><aside class="planner-catalog"><div class="catalog-search"><Search :size="18"/><input v-model="query" placeholder="Szukaj miejsc…" aria-label="Szukaj w katalogu"></div><div class="catalog-tabs"><button :class="{active:category==='all'}" @click="category='all'">Wszystkie</button><button v-for="c in categories.filter(c=>['nature','heritage','food'].includes(c.id))" :key="c.id" :class="{active:category===c.id}" @click="category=c.id">{{c.name}}</button></div><p class="catalog-caption">{{filtered.length}} miejsc do odkrycia</p><button v-for="place in filtered" :key="place.id" :class="['catalog-place',{selected:selected.includes(place.id)}]" @click="togglePlace(place.id)"><img :src="place.image" :alt="place.name"><span><strong>{{place.name}}</strong><small>{{place.subtitle}}</small><em><MapPin :size="11"/>{{place.location}}</em></span><span class="checkbox"><Check v-if="selected.includes(place.id)" :size="14"/><Plus v-else :size="14"/></span></button><p v-if="!filtered.length" class="small-note">Brak wyników. Zmień wyszukiwaną nazwę.</p></aside>
   <div class="map-panel"><TravelMap :places="places" :selected="selected" :geometry="computedRoute?.geometry" @select="togglePlace"/><div class="map-badge"><span class="live-dot"></span> Ziemia Lubuska <span>·</span> Twój plan podróży</div><div class="map-disclaimer"><Navigation :size="14"/>{{routeLoading?'Wyznaczanie trasy…':computedRoute?'Trasa BRouter · dane OpenStreetMap':'Wybierz punkty i trasę pieszą lub rowerową.'}}</div></div>
   <aside class="route-panel"><div class="route-title"><h2>Twoja trasa <span>{{selected.length}}</span></h2><button @click="selected=[]" :disabled="!selected.length">Resetuj</button></div><div class="route-list"><article v-for="(place,index) in selectedPlaces" :key="place.id" class="route-stop"><span class="stop-number">{{index+1}}</span><img :src="place.image" :alt="place.name"><div><strong>{{place.name}}</strong><small>{{place.location}}</small></div><div class="stop-actions"><button :disabled="index===0" @click="move(index,-1)" :aria-label="`Przesuń ${place.name} wyżej`"><ChevronUp :size="14"/></button><button :disabled="index===selected.length-1" @click="move(index,1)" :aria-label="`Przesuń ${place.name} niżej`"><ChevronDown :size="14"/></button><button @click="togglePlace(place.id)" :aria-label="`Usuń ${place.name} z trasy`"><X :size="13"/></button></div></article><div v-if="!selected.length" class="route-empty"><MapPin :size="32"/><p>Każda przygoda ma początek.<br>Dodaj pierwsze miejsce z katalogu.</p></div></div><div class="transport-select"><button v-for="t in [{id:'bike',label:'Rowerem',icon:Bike},{id:'walk',label:'Pieszo',icon:Footprints},{id:'car',label:'Autem',icon:Navigation}]" :key="t.id" :class="{active:transport===t.id}" @click="transport=t.id"><component :is="t.icon" :size="21"/>{{t.label}}</button></div><div class="route-stats"><span><strong>{{distance}} km</strong><small>{{computedRoute?'Dystans trasy':'W linii prostej'}}</small></span><span><strong>~ {{travelTime}}</strong><small>Czas bez postojów</small></span></div><div class="routing-status" role="status"><p v-if="routeLoading">Wyznaczam trasę po drogach i ścieżkach…</p><p v-else-if="routeError" class="routing-error">{{routeError}} <button @click="refreshRoute">Spróbuj ponownie</button></p><p v-else-if="computedRoute">{{transport==='bike'?'Trasa rowerowa':'Trasa piesza'}} · BRouter / OpenStreetMap. Czas jest orientacyjny, bez postojów. Sprawdź warunki w terenie.</p><p v-else-if="transport==='car'">Tryb samochodowy zapisuje punkty bez wyznaczania przebiegu dróg.</p><p v-else-if="!apiOnline">Wyznaczanie trasy wymaga połączenia z serwerem.</p><p v-else>Dodaj co najmniej dwa miejsca, aby wyznaczyć trasę.</p></div><button class="button full-width" :disabled="!selected.length||routeLoading" @click="exportGpx"><Download :size="18"/> {{computedRoute?'Pobierz trasę (GPX)':'Pobierz punkty (GPX)'}}</button><button class="button outline full-width" :disabled="!selected.length" @click="modal='save'"><Heart :size="18"/> Zapisz plan wycieczki</button></aside>
  </section>
 </main>

 <main v-else class="about-page content-width"><div class="section-kicker">DOBRZE BYĆ BLISKO</div><h1>Ziemia Lubuska.<br><em>Naturalnie niezwykła.</em></h1><img src="/images/hero.webp" alt="Jezioro i zamek otoczone lasem"><div class="about-copy"><h2>Przestrzeń na małe odkrycia</h2><p>Między jeziorami, lasami i historycznymi miasteczkami czeka region, który najlepiej poznaje się bez pośpiechu. Od Łagowa po Park Mużakowski, od podziemnych historii po rozlewiska Warty — znajdź własny powód, żeby tu wrócić.</p><p>Perły Ziemi Lubuskiej to projekt pomagający zbierać pomysły na wycieczki. Opisy i zdjęcia mają charakter inspiracyjny. Przed wyjazdem sprawdź godziny otwarcia i dostępność wybranych atrakcji.</p><button class="button" @click="navigate('discover')">Znajdź swoją perłę <ArrowRight :size="18"/></button></div></main>

 <footer class="content-width"><a class="footer-brand" href="#" @click.prevent="navigate('explore')"><Trees :size="25"/>Perły Ziemi Lubuskiej</a><span>Blisko natury. Bliżej siebie.</span><div><span :class="['connection-status',{online:apiOnline}]"></span>{{apiOnline?'Połączono z serwerem':'Tryb demonstracyjny · dane lokalne'}}</div><small>© {{new Date().getFullYear()}} Perły Ziemi Lubuskiej</small></footer>

 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="18"/>{{toast}}<button @click="toast=''" aria-label="Zamknij komunikat"><X :size="16"/></button></div></Transition>
 <div v-if="modal" class="modal-overlay" @click.self="modal=null" @keydown.esc="modal=null" @keydown="trapFocus"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='detail'?detail.name:modal==='auth'?'Konto użytkownika':'Zapisane plany'" tabindex="-1"><button class="modal-close icon-btn" @click="modal=null" aria-label="Zamknij okno"><X :size="22"/></button>
  <template v-if="modal==='detail'"><img class="detail-image" :src="detail.image" :alt="detail.name"><div class="modal-body"><div class="section-kicker">{{detail.location}}</div><h2>{{detail.name}}</h2><p>{{detail.description}}</p><div class="detail-actions"><button class="button" @click="if(!selected.includes(detail.id))selected.push(detail.id);modal=null;navigate('planner')"><Plus :size="18"/>Dodaj do wycieczki</button><button class="button outline" @click="toggleFavorite(detail.id)"><Heart :size="18" :fill="favorites.includes(detail.id)?'currentColor':'none'"/>Ulubione</button></div><a class="button outline full-width google-maps-link" :href="googleMapsUrl" target="_blank" rel="noopener noreferrer"><MapPin :size="17"/>Otwórz w Google Maps<ArrowUpRight :size="16"/></a><PlaceCommunity :place="detail" :user="user" :token="token" :online="apiOnline" @login="requestPlaceLogin" @notify="notify"/></div></template>
  <div v-else-if="modal==='auth'" class="modal-body auth-body"><div class="section-kicker">TWOJE MIEJSCE NA PRZYGODY</div><h2>{{authMode==='login'?'Dobrze Cię widzieć.':'Zacznij swoją podróż.'}}</h2><p>Zapisuj ulubione miejsca i plany wycieczek na swoim koncie.</p><div v-if="!apiOnline" class="api-notice">Logowanie wymaga uruchomionego backendu. Teraz możesz odkrywać miejsca i zapisywać plany lokalnie na tym urządzeniu.</div><form @submit.prevent="authenticate"><label v-if="authMode==='register'">Twoje imię<input v-model="authName" required maxlength="80" autocomplete="given-name"></label><label>Adres e-mail<input v-model="authEmail" type="email" required autocomplete="email"></label><label>Hasło<input v-model="authPassword" type="password" required minlength="8" maxlength="128" :autocomplete="authMode==='login'?'current-password':'new-password'" placeholder="Minimum 8 znaków"></label><p v-if="authError" class="form-error" role="alert">{{authError}}</p><button class="button full-width" :disabled="busy||!apiOnline">{{busy?'Chwileczkę…':authMode==='login'?'Zaloguj się':'Utwórz konto'}}<ArrowRight :size="17"/></button></form><button class="auth-switch" @click="authMode=authMode==='login'?'register':'login';authError=''">{{authMode==='login'?'Nie masz konta? Zarejestruj się':'Masz już konto? Zaloguj się'}}</button></div>
  <div v-else-if="modal==='save'" class="modal-body"><div class="section-kicker">ZACHOWAJ TEN POMYSŁ</div><h2>Jeszcze tu wrócisz.</h2><label>Nazwa Twojej wycieczki<input v-model="routeName" maxlength="120" placeholder="Moja lubuska przygoda"></label><p>{{selected.length}} punktów · {{distance}} km {{computedRoute?'po trasie':'w linii prostej'}}</p><p class="small-note">{{user&&apiOnline?'Plan zostanie zapisany na Twoim koncie.':'Plan zostanie zapisany w przeglądarce na tym urządzeniu.'}}</p><button class="button full-width" :disabled="!routeName.trim()" @click="saveRoute">Zapisz plan <Check :size="18"/></button></div>
  <div v-else-if="modal==='saved'" class="modal-body"><div class="section-kicker">POMYSŁY NA KOLEJNY WOLNY DZIEŃ</div><h2>Zapisane plany</h2><p v-if="!savedPlans.length">Nie masz jeszcze zapisanych planów. Wybierz miejsca na mapie i zapisz swoją pierwszą wycieczkę.</p><article v-for="route in savedPlans" :key="route.id" class="saved-route"><button @click="selected=[...route.place_ids];transport=route.transport;routeName=route.name;modal=null"><Route :size="22"/><span><strong>{{route.name}}</strong><small>{{route.place_ids.length}} miejsc</small></span><ArrowRight :size="18"/></button><button class="icon-btn" @click="deleteSaved(route)" aria-label="Usuń zapisany plan"><X :size="16"/></button></article></div>
 </section></div>
</template>
